//! Auto-generated trait/talent data from WoW CSV exports.
//! Do not edit manually - regenerate with: wow-cli generate traits

#[derive(Debug, Clone)]
pub struct TraitTreeInfo {
    pub id: u32,
    pub first_node_id: u32,
    pub flags: u32,
    pub node_ids: &'static [u32],
    pub currency_ids: &'static [u32],
}

#[derive(Debug, Clone)]
pub struct TraitNodeInfo {
    pub id: u32,
    pub tree_id: u32,
    pub pos_x: i32,
    pub pos_y: i32,
    pub node_type: u32,
    pub flags: u32,
    pub sub_tree_id: u32,
    pub entry_ids: &'static [u32],
    pub cond_ids: &'static [u32],
    pub edges: &'static [TraitEdgeInfo],
    pub group_ids: &'static [u32],
    pub group_cond_ids: &'static [u32],
}

#[derive(Debug, Clone)]
pub struct TraitEntryInfo {
    pub id: u32,
    pub definition_id: u32,
    pub max_ranks: u32,
    pub entry_type: u32,
    pub sub_tree_id: u32,
}

#[derive(Debug, Clone)]
pub struct TraitDefInfo {
    pub id: u32,
    pub spell_id: u32,
    pub override_icon: u32,
    pub overrides_spell_id: u32,
    pub visible_spell_id: u32,
    pub override_name: &'static str,
    pub override_subtext: &'static str,
    pub override_description: &'static str,
}

#[derive(Debug, Clone)]
pub struct TraitCondInfo {
    pub id: u32,
    pub cond_type: u32,
    pub tree_id: u32,
    pub granted_ranks: u32,
    pub quest_id: u32,
    pub achievement_id: u32,
    pub spec_set_id: u32,
    pub group_id: u32,
    pub node_id: u32,
    pub entry_id: u32,
    pub currency_id: u32,
    pub spent_amount: u32,
    pub flags: u32,
    pub required_level: u32,
}

#[derive(Debug, Clone)]
pub struct TraitSubTreeInfo {
    pub id: u32,
    pub name: &'static str,
    pub description: &'static str,
    pub atlas_element_id: u32,
    pub tree_id: u32,
}

#[derive(Debug, Clone)]
pub struct TraitCurrencyInfo {
    pub id: u32,
    pub currency_type: u32,
    pub flags: u32,
}

#[derive(Debug, Clone)]
pub struct TraitEdgeInfo {
    pub source_node_id: u32,
    pub edge_type: u32,
    pub visual_style: u32,
}

