#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_tree_count() {
        assert!(TRAIT_TREE_DB.len() > 100);
    }

    #[test]
    fn test_paladin_tree_790() {
        let tree = TRAIT_TREE_DB.get(&790).expect("tree 790");
        assert_eq!(tree.node_ids.len(), 237);
    }

    #[test]
    fn test_node_has_entries() {
        let tree = TRAIT_TREE_DB.get(&790).expect("tree 790");
        let first_node_id = tree.node_ids[0];
        let node = TRAIT_NODE_DB.get(&first_node_id).expect("first node");
        assert!(!node.entry_ids.is_empty());
    }

    #[test]
    fn test_definition_count() {
        assert!(TRAIT_DEFINITION_DB.len() > 10_000);
    }
}
